-- The proof of funds services' texts as the consultant rewrote them (prices, contract and the rest untouched).
UPDATE "document_service"
SET "summary" = '{"fr":"Vous disposez déjà des fonds requis pour votre demande de résidence permanente au Canada ? Stanzy structure votre preuve de fonds : un dépôt initial en microfinance, suivi d’un transfert vers le compte bancaire de votre choix. Dites adieu aux risques de refus liés à la transférabilité des fonds !\n\nNous constituons avec vous un dossier complet de preuve de fonds :\n• les justificatifs bancaires nécessaires ;\n• la traçabilité et la justification de la source des fonds ;\n• la cohérence des mouvements financiers ;\n• une documentation structurée, conforme aux exigences d’IRCC.\n\nAvec Stanzy, votre preuve de fonds ne se limite pas à un solde bancaire : elle repose sur un dossier documenté et cohérent.","en":"You already have the funds required for your Canadian permanent residence application? Stanzy structures your proof of funds: an initial deposit in microfinance, followed by a transfer to the bank account of your choice. Say goodbye to refusals over the transferability of funds!\n\nWe build a complete proof of funds file with you:\n• the bank documents required;\n• the traceability and justification of the source of funds;\n• consistent financial movements;\n• structured documentation that meets IRCC’s requirements.\n\nWith Stanzy, your proof of funds is more than a bank balance: it rests on a documented, consistent file."}'::jsonb, "provides" = '{"fr":"Votre pièce d’identité, la taille de votre famille, la date prévue de votre profil ou de votre ITA, et la banque vers laquelle transférer les fonds.","en":"Your ID, your family size, the expected date of your profile or ITA, and the bank to transfer the funds to."}'::jsonb, "turnaround" = '{"fr":"Environ 3 semaines après le démarrage de la procédure","en":"About 3 weeks once the procedure starts"}'::jsonb, "conditions" = '{"fr":"La procédure débute uniquement après le versement des honoraires. Ces honoraires, un pourcentage du montant à justifier, couvrent tout le processus de constitution et de sécurisation de la preuve de fonds. Les fonds doivent être à votre nom et disponibles.","en":"The procedure only starts once the fee is paid. The fee, a percentage of the amount to justify, covers the whole process of building and securing the proof of funds. The funds must be in your name and available."}'::jsonb
WHERE "slug" = 'preuve-de-fonds';

UPDATE "document_service"
SET "summary" = '{"fr":"Vous ne disposez pas des fonds requis pour votre demande de résidence permanente au Canada ? Stanzy les met à votre disposition, avec une preuve de fonds structurée : un dépôt initial en microfinance, suivi d’un transfert bancaire vers un compte UBA. Dites adieu aux risques de refus liés à la transférabilité des fonds !\n\nNous constituons avec vous un dossier complet de preuve de fonds :\n• les justificatifs bancaires nécessaires ;\n• la traçabilité et la justification de la source des fonds ;\n• la cohérence des mouvements financiers ;\n• une documentation structurée, conforme aux exigences d’IRCC.\n\nAvec Stanzy, votre preuve de fonds ne se limite pas à un solde bancaire : elle repose sur un dossier documenté et cohérent.","en":"You don’t have the funds required for your Canadian permanent residence application? Stanzy provides them, with a structured proof of funds: an initial deposit in microfinance, followed by a bank transfer to a UBA account. Say goodbye to refusals over the transferability of funds!\n\nWe build a complete proof of funds file with you:\n• the bank documents required;\n• the traceability and justification of the source of funds;\n• consistent financial movements;\n• structured documentation that meets IRCC’s requirements.\n\nWith Stanzy, your proof of funds is more than a bank balance: it rests on a documented, consistent file."}'::jsonb, "provides" = '{"fr":"Votre pièce d’identité, la taille de votre famille et la date prévue de votre profil ou de votre ITA.","en":"Your ID, your family size and the expected date of your profile or ITA."}'::jsonb, "turnaround" = '{"fr":"Environ 3 semaines après le démarrage de la procédure","en":"About 3 weeks once the procedure starts"}'::jsonb, "conditions" = '{"fr":"La procédure débute uniquement après le versement des honoraires. Ces honoraires, un pourcentage du montant à justifier, comprennent la mise à disposition des fonds ainsi que tout le processus de constitution et de sécurisation de la preuve de fonds. Si vous avez déjà un compte UBA, il doit être fermé : un nouveau compte est ouvert à votre nom.","en":"The procedure only starts once the fee is paid. The fee, a percentage of the amount to justify, covers providing the funds and the whole process of building and securing the proof of funds. If you already have a UBA account, it must be closed: a new account is opened in your name."}'::jsonb
WHERE "slug" = 'preuve-de-fonds-sans-fonds';

